#!/usr/bin/env python3

"""
Script to reproduce the bug with mocked classmethod.
"""

import pytest
from oop_ext.interface import Interface, ImplementsInterface, AssertImplements


def testRequiresDeclarationBug():
    """Reproducing the failing test case from the issue description."""

    class IFoo(Interface):
        @classmethod
        def foo(cls):
            ""

    @ImplementsInterface(IFoo)
    class FooImplementation:
        @classmethod
        def foo(cls):
            ""

    # Import mocker fixture equivalent
    from unittest import mock

    # Mock the classmethod using spy equivalent
    with mock.patch.object(FooImplementation, "foo"):
        # This should pass but currently fails
        AssertImplements(FooImplementation, IFoo, requires_declaration=True)


def test_with_pytest_mocker():
    """Test with pytest-mock style mocker as mentioned in issue."""

    class IFoo(Interface):
        @classmethod
        def foo(cls):
            ""

    @ImplementsInterface(IFoo)
    class FooImplementation:
        @classmethod
        def foo(cls):
            ""

    # Simulate mocker.spy behavior
    from unittest import mock

    # Using patch.object similar to mocker.spy
    with mock.patch.object(FooImplementation, "foo") as mock_foo:
        print(f"Type of mocked foo: {type(mock_foo)}")
        print(f"Mocked foo: {mock_foo}")

        # Check if it's recognized as a method
        import inspect
        from oop_ext.interface._interface import _IsMethod

        foo_attr = getattr(FooImplementation, "foo")
        print(f"_IsMethod result: {_IsMethod(foo_attr)}")
        print(f"isfunction: {inspect.isfunction(foo_attr)}")
        print(f"ismethod: {inspect.ismethod(foo_attr)}")
        print(f"type: {type(foo_attr)}")

        try:
            AssertImplements(FooImplementation, IFoo, requires_declaration=True)
            print("SUCCESS: AssertImplements passed!")
        except AssertionError as e:
            print(f"FAILED: {e}")
            raise


if __name__ == "__main__":
    print("Testing with pytest-mock style...")
    test_with_pytest_mocker()

