from oop_ext.interface import Interface, ImplementsInterface, IsImplementation
from unittest import mock

def test_direct_mock():
    """Mock the method directly in the class being checked."""

    class II(Interface):
        def foo(self, a, b, c):
            pass

    @ImplementsInterface(II)
    class Foo:
        def foo(self, a, b, c):
            pass

    print("=== DIRECT MOCK ON SAME CLASS ===")
    print(f"Before mock: {IsImplementation(Foo, II)}")

    with mock.patch.object(Foo, "foo", autospec=False):
        print(f"After autospec=False mock: {IsImplementation(Foo, II)}")


def test_inherited_mock():
    """Mock the method in parent, check child."""

    class II(Interface):
        def foo(self, a, b, c):
            pass

    @ImplementsInterface(II)
    class Foo:
        def foo(self, a, b, c):
            pass

    class Bar(Foo):
        pass

    print("\n=== MOCK ON PARENT, CHECK CHILD ===")
    print(f"Before mock: {IsImplementation(Bar, II)}")

    with mock.patch.object(Foo, "foo", autospec=False):
        print(f"After autospec=False mock: {IsImplementation(Bar, II)}")


if __name__ == "__main__":
    test_direct_mock()
    test_inherited_mock()

