"""
Test to verify that autospec=False should make interface checking fail.
"""

from oop_ext.interface import Interface, ImplementsInterface, IsImplementation
from unittest import mock


def test_autospec_false_should_fail():
    """This should demonstrate the expected failing behavior."""

    class II(Interface):
        def foo(self, a, b, c):
            pass

    @ImplementsInterface(II)
    class Foo:
        def foo(self, a, b, c):
            pass

    class Bar(Foo):
        pass

    print("Before mocking:")
    print(f"IsImplementation(Bar, II): {IsImplementation(Bar, II)}")

    # Test with autospec=False - this should make the check fail
    with mock.patch.object(Foo, "foo", autospec=False):
        result = IsImplementation(Bar, II)
        print(f"After autospec=False mock: {result}")
        print("This SHOULD be False according to the original test expectation")


def test_autospec_true_should_pass():
    """This should demonstrate the expected passing behavior."""

    class II(Interface):
        def foo(self, a, b, c):
            pass

    @ImplementsInterface(II)
    class Foo:
        def foo(self, a, b, c):
            pass

    class Bar(Foo):
        pass

    print("\nBefore mocking:")
    print(f"IsImplementation(Bar, II): {IsImplementation(Bar, II)}")

    # Test with autospec=True - this should make the check pass
    with mock.patch.object(Foo, "foo", autospec=True):
        result = IsImplementation(Bar, II)
        print(f"After autospec=True mock: {result}")
        print("This SHOULD be True according to the original test expectation")


if __name__ == "__main__":
    test_autospec_false_should_fail()
    test_autospec_true_should_pass()

