# Test to reproduce the original issue without pytest

from oop_ext.interface import Interface, ImplementsInterface, AssertImplements
from unittest import mock


def test_original_issue_without_pytest():
    """Try to reproduce the issue manually."""

    class IFoo(Interface):
        @classmethod
        def foo(cls):
            ""

    @ImplementsInterface(IFoo)
    class FooImplementation:
        @classmethod
        def foo(cls):
            ""

    print("Before mocking:")
    foo_attr = getattr(FooImplementation, "foo")
    from oop_ext.interface._interface import _IsMethod
    print(f"_IsMethod result: {_IsMethod(foo_attr)}")
    print(f"type: {type(foo_attr)}")

    # Manually create a spy-like mock
    original_foo = getattr(FooImplementation, "foo")
    spy_mock = mock.MagicMock(side_effect=original_foo)

    with mock.patch.object(FooImplementation, "foo", spy_mock):
        print("\nAfter mocking with spy:")
        foo_attr = getattr(FooImplementation, "foo")
        print(f"_IsMethod result: {_IsMethod(foo_attr)}")
        print(f"type: {type(foo_attr)}")
        print(f"side_effect: {foo_attr.side_effect}")

        try:
            AssertImplements(FooImplementation, IFoo, requires_declaration=True)
            print("SUCCESS: AssertImplements passed!")
            return True
        except AssertionError as e:
            print(f"FAILED: {e}")
            return False


def test_without_side_effect():
    """Test with a mock that has no side_effect (like autospec=False)."""

    class IFoo(Interface):
        @classmethod
        def foo(cls):
            ""

    @ImplementsInterface(IFoo)
    class FooImplementation:
        @classmethod
        def foo(cls):
            ""

    print("\n" + "="*50)
    print("Testing mock WITHOUT side_effect (like autospec=False):")

    # Mock without preserving original behavior
    regular_mock = mock.MagicMock()  # No side_effect

    with mock.patch.object(FooImplementation, "foo", regular_mock):
        print("After mocking without side_effect:")
        foo_attr = getattr(FooImplementation, "foo")
        print(f"_IsMethod result: {_IsMethod(foo_attr)}")
        print(f"type: {type(foo_attr)}")
        print(f"side_effect: {getattr(foo_attr, 'side_effect', 'NO ATTR')}")

        try:
            AssertImplements(FooImplementation, IFoo, requires_declaration=True)
            print("SUCCESS: AssertImplements passed!")
            return True
        except AssertionError as e:
            print(f"FAILED: {e}")
            return False


if __name__ == "__main__":
    result1 = test_original_issue_without_pytest()
    result2 = test_without_side_effect()

    print("\n" + "="*50)
    print("SUMMARY:")
    print(f"Spi-like mock (with side_effect): {'PASS' if result1 else 'FAIL'}")
    print(f"Regular mock (no side_effect): {'PASS' if result2 else 'FAIL'}")
